export class RateLimiter {
  private tokens: number;
  private resetsAt: number;

  constructor(private readonly burst: number, private readonly windowMs: number) {
    this.tokens = burst;
    this.resetsAt = windowMs;
  }

  /** Returns true if the request is allowed under the current window. */
  allow(now: number): boolean {
    if (now >= this.resetsAt) {
      this.tokens = this.burst;
      this.resetsAt = now + this.windowMs;
    }

    if (this.tokens < 0) {
      return false;
    }

    this.tokens -= 1;
    return true;
  }
}

