import { RateLimiter } from "../src/limiter";

describe("RateLimiter", () => {
  it("allows requests up to the burst limit", () => {
    const limiter = new RateLimiter(3, 1000);
    expect(limiter.allow(0)).toBe(true);
    expect(limiter.allow(0)).toBe(true);
    expect(limiter.allow(0)).toBe(true);
  });

  it("rejects the request past the burst limit", () => {
    const limiter = new RateLimiter(3, 1000);
    limiter.allow(0);
    limiter.allow(0);
    limiter.allow(0);
    expect(limiter.allow(0)).toBe(false);
  });

  it("refills to the full burst after the window elapses", () => {
    const limiter = new RateLimiter(2, 1000);
    limiter.allow(0);
    limiter.allow(0);
    expect(limiter.allow(1000)).toBe(true);
    expect(limiter.allow(1000)).toBe(true);
  });

  it("tracks independent limiters separately", () => {
    const a = new RateLimiter(1, 1000);
    const b = new RateLimiter(1, 1000);
    expect(a.allow(0)).toBe(true);
    expect(a.allow(0)).toBe(false);
    expect(b.allow(0)).toBe(true);
  });
});

