import { RateLimiter } from "../../src/limiter";

describe("window rollover", () => {
  it("keeps window boundaries fixed to multiples of windowMs, even when a request arrives late and triggers the reset", () => {
    const limiter = new RateLimiter(1, 1000);
    limiter.allow(0);
    expect(limiter.allow(1200)).toBe(true);
    expect(limiter.allow(1999)).toBe(false);
    expect(limiter.allow(2000)).toBe(true);
  });
});

